import numpy as np, json
lines = open('optimized.xyz').readlines()
n=int(lines[0]); syms=[]; co=[]
for l in lines[2:2+n]:
    p=l.split(); syms.append(p[0]); co.append([float(p[1]),float(p[2]),float(p[3])])
co=np.array(co)
# bond perception by covalent radii
cov={'H':0.31,'C':0.76,'N':0.71,'O':0.66,'F':0.57,'P':1.07,'S':1.05,'Si':1.11,'Rh':1.42}
bonds=set()
for i in range(n):
    for j in range(i+1,n):
        d=np.linalg.norm(co[i]-co[j])
        if d < (cov[syms[i]]+cov[syms[j]])*1.25:
            bonds.add((i,j))
# build adjacency for 1-3 exclusion
adj={i:set() for i in range(n)}
for i,j in bonds: adj[i].add(j); adj[j].add(i)
def is13(i,j):
    return any(k in adj[j] for k in adj[i])
vdw={'H':1.20,'C':1.70,'N':1.55,'O':1.52,'F':1.47,'P':1.80,'S':1.80,'Si':2.10,'Rh':2.00}
print('shortest NON-bonded, non-1,3 contacts:')
res=[]
for i in range(n):
    for j in range(i+1,n):
        if (i,j) in bonds or is13(i,j): continue
        d=np.linalg.norm(co[i]-co[j])
        res.append((d,i,j))
res.sort()
for d,i,j in res[:12]:
    print(f'  {i:3d}{syms[i]:2s}..{j:3d}{syms[j]:2s} d={d:.2f}  vdw_sum={vdw[syms[i]]+vdw[syms[j]]:.2f}')
print('num bonds detected:', len(bonds))
"
